namespace OpenTPW;

/// <summary>
/// Register of the original-save import mappings that are not traced (docs/reverse/SAVE-plan.md §8.2,
/// docs/SAVE-CONTAINER.md, "Import into OpenTPW"). Each entry has a matching <c>// [APPROX:SAVE-NNN]</c>
/// comment at its code site. Values the import drops are also reported in <see cref="OriginalEconomyImport.Evidence"/>.
/// </summary>
public static class SaveApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("SAVE-001", "the save's world generator word (mRandomSeed) is reported but not imported. It is the whole state of the original's one shared world LCG (tp.exe 0x516330 on world +0x1DA708: s = s × 0x19660D + 0x3C6EF35F, rotated right by 13, absolute value returned), written raw by the world saver (0x51710E) and read back raw by the loader (0x517DE7); a new park seeds it from time() (0x515879). OpenTPW's economy, guest and script streams are separate generators derived from the world seed, so restoring the word alone would reproduce no draw", "DET-I2 port of the world LCG with the original's call order (DET-005, DET-013), then restoring this word"),
		("SAVE-002", "a saved guest in a queue or boarding (states 11–14), leaving a ride (15), using an attraction (16) or held by a guard (17) is not imported, nor is a park guest off the paths, a guard escorting a guest is imported idle and one chasing a guest the import does not restore gives the chase up at his first update; an imported guest in an activity (state 8) decides again at once, one at the booth (4) waits OpenTPW's booth time rather than its saved wait (+0x200), a paid guest waiting for the gate (3) walks in at once (GUEST-011), an arriving or departing guest walks OpenTPW's nearest arrival lane from where it stands, a turn stamp before the save's turn counts from the import, and the arrival date and index, the admission flags, the shop, sideshow and win counts, the event ring and the queue links are not imported", "an OpenTPW queue and rider restore for original guests; the booth's and the gate's waits in OpenTPW's arrival model"),
		("SAVE-004", "the pool's sub-type and on-pointer bytes are not imported: a candidate's sub-type (+9) is drawn at its creation (0x507600 → 0x541F70, (R >> 2) % a per-model count of the table 0x763F90 that is filled at run time) and handed to the placement object 0x46C6D0 when it is picked up (0x507BF0), which also sets its on-pointer byte (+0xB); OpenTPW keeps no staff sub-type and does not save the placement in hand. The people-in-category counts and stop-producing flags need no import: the census 0x508000 recomputes them from the park's staff before every read (the refill 0x5084F0, its top-up 0x508170 and the pick-up 0x507BF0), as UpdatePool counts the hired staff; the opening-pool flag only gates the opening pool 0x5087D0, which OpenTPW draws for a new park only", "what the sub-type selects in the placement object 0x46C6D0 and the per-model counts at 0x763F90"),
		("SAVE-005", "the challenge slots' loss counts, the follow-up's carried object and the day an unanswered offer was made are not imported, and the first offer does not wait for an open park", "what reads the loss counts and how the follow-up types read the carried object"),
		("SAVE-006", "an attraction's operating capacity, duration and speed (OpenTPW's rides keep their tier's Init values, as the shipped saves do), a closed open word of a working attraction (mCanLoad: the park door opens it), the six daily 30-day rings (OpenTPW keeps this and last month and, apart, a 30-day ring of walk-aways that starts empty at the import, ECON-057), its sign lines (OpenTPW names no attraction), the third gauge (+0x4C, no reader found in the attraction code) and a staff claim no imported job holds (an imported job's claim is taken again with its saved turn, 0x004E01F0; any other claim is dropped, and a claim lapses 100 turns after its turn unless its claimant still targets the object, 0x004E0220, ECON-022) are not imported; the raw links (mesh instance, script and track handles, flags, footprint, entrance and exit cells, upgrade parent, balloon sprite) are rebuilt by the placement and the queue (cells, ends, called guest) from the laid queue cells", "the import of the operating words into the restored rides' runtimes; the readers of the daily rings and of +0x4C"),
		("SAVE-007", "lab projects OpenTPW does not list are dropped, a saved current project OpenTPW would not research now is not selected, the save's highest open group is recomputed, and the object table's researched flags are not read", "the object table's researched flags (+0x10, outside the lab block)"),
		("SAVE-008", "the batch balance is not imported: in tp.exe the batch word +0x10 is a pending credit that the bank's month message adds to the balance, the money-in total and the year's profit and then zeroes (0x4D0393..0x4D03DB); the loan offers' stored credit tests (Available, +0x14) are imported, the constructor having started each as amount at most 10,000 (0x4CF84B). The ledger month opens at the current balance; the bank keeps no month-opening word, mLastBalance being the balance after the last debit, instalment or payoff (0x4D0228, 0x4D08E1)", "a save with a non-zero batch word"),
		("SAVE-009", "the staff HQ's picked-up staff id (+0x60) is not imported: it is set when a member is picked up (0x509AE0 from 0x505C50) and read and cleared when the placement tool puts it down (0x509AF0 from 0x46CC40), and OpenTPW does not save a member in hand. The force-strike word and the trained byte need no import: the force strike (+0x64) is written only by the HQ constructor 0x5089C0 (0) and the save loader 0x508BB0, so the month gate 0x508E70 and the grievance 0x509360 see 0 in play as OpenTPW does, and the trained byte (mHaveEverTrained, training +0x14) is only cleared (0x50C620) and serialized (0x50C640), never read", "what a save made with a staff member in hand restores"),
		("SAVE-010", "the opaque blocks (scripts, particles, messages, clock words, cadence, track/flying rides, RSSE, camera, advisor presentation, sound, cheats, advisor scoring, UI) and the Coasters block, whose structure SaveCoasterBlock now reads (SAVE-920 to SAVE-923) without importing any state, the weather, park analyser, tag system, mechanic HQ and UI message receiver things, the world state, arrival variables and arrival bytes, the calendar session start and the advisor controller's time signature, sound, three raw words, mRequestedLastTutorial and mMessagePlaying are not imported (its current record is imported as the last tutorial advice when an automatic advisor attaches), nor are its pending advice and history when no automatic advisor is attached; of the cell map only path cells, occupancy, MAP attributes and each path cell's texture and turn are read (so a handyman walking to or sweeping litter is imported idle), and a saved path tile is drawn only while the cell's path neighbours equal the saved ones and its turn is 0/90/180/270 (otherwise the tile is chosen from the neighbours); object scripts restart from their archives, where the original's RSSE loader (tp.exe 0x5597A0: header RSSE, then per script its 0xF4-byte record and saved buffers, then its OBJ list) restores every script's saved state", "decoded block layouts and the original's post-load reconstruction"),
		("SAVE-011", "the delimiters of blocks whose width is not traced are located by their bytes: a payload that splits into its blocks in more than one way, or holds a delimiter's bytes more than MaximumDelimiterOccurrences times, is rejected, while the original loader (tp.exe 0x415270) runs each block's own reader and then compares the next 4 bytes with the block's tag (WRLD at 0x415371), failing on a mismatch, so it never searches and loads such payloads", "the serialized widths of the remaining blocks (their PC readers: message centre 0x40FD60, game system 0x5506E0, ride system 0x4647A0, track rides 0x543560, flying rides 0x55E020, RSSE 0x5597A0, camera 0x42CEC0, coasters 0x437B60, advisor 0x599D00, sound 0x51C400)"),
		("SAVE-920", "a Coasters block (the body between the stored EMAK and SAOC delimiters) that lists more than one coaster is refused: the original's loader (tp.exe 0x437B60) reads every coaster in turn, and each coaster's train payload holds one 27-byte record per train slot of its type (the type's +0x2E8 count, 0x438386) and per car an 11-byte record followed by its two counted u32 lists, so its extent needs the coaster type's train and car counts, which this Files-layer reader does not have", "the coaster type's train slot and car counts passed to the reader (type +0x2E8 and the car list count); a nonempty original Coasters block"),
		("SAVE-921", "the coaster header and section flag words are remapped controller and node flags; they are kept raw and no bit is interpreted. The section map is traced in tp.exe: the saver (0x437615..0x4376E0) writes memory bits 0x1/0x2/0x4/0x80/0x40/0x100/0x10000/0x20000/0x40000/0x80000/0x200000/0x400000 as wire 0x1/0x2/0x4/0x8/0x10/0x20/0x40/0x80/0x100/0x200/0x400/0x800, and the loader (0x437EA6..0x437F58) sets 0x1/0x2/0x4, 0x10000, 0x20000, 0x40000, 0x80000, 0x200000 and 0x400000 back but not 0x80, 0x40 or 0x100", "the meaning of the remapped bits and of wire 0x8/0x10/0x20 on load; the header word's map at instruction level"),
		("SAVE-922", "the coaster header's controller words (+8, +12, +16, +20, +28, +32, +244, +240), the block's three globals, the auxiliary ordinals' meaning, the word section+112 and the section floats +220/+224/+248 are saved but their meaning is not traced; they are reported raw (+248 matches the loop-rotate slider's node +248 by offset only). Traced in tp.exe's loader 0x437B60: the controller word +16 is matched against the live coasters' +0x10 to bind the block to an existing coaster (0x437CBF; none matching dereferences null, 0x437CD5), the three globals are the coaster slot allocator's state (0x790B04, 0x790B00, 0x791CE0, passed to 0x468760, whose slot is stored in the controller's +0x14) and +240 is restored to the controller's +0xF0 (0x438373), which 0x43BA90 copies to the room capacity +0xB8 (0x43BBD1)", "the readers of the controller words +8, +12, +28, +32 and +244 and of the section words in the original coaster module"),
		("SAVE-923", "the train/car/passenger payload that follows each coaster's sections is not decoded; it is preserved as raw bytes and never interpreted, and no original coaster chunk is written. Its layout is traced in tp.exe (saver 0x437300, loader 0x437B60): per train slot a 27-byte record (u32 flags, u8 train +0xC, u32 train +0x74, +0x78, +0x38, +0x64, +0x68, u16 train +0x10; 0x43783B), then per car an 11-byte record (u32 flags, u8 counts A and B from car +0x30/+0x34, u8 car +0x44, u32 car +0xC; 0x4378A5) and A then B u32 entries from the car's lists +0x28/+0x2C", "the meanings of the train and car words; the bytes of a nonempty original Coasters block"),
	};
